import re
import requests

def task_func(input):
    match = re.search(r'https?://[^\s\'"<>)]+', input)
    if not match:
        return {"error": "No endpoint found"}

    endpoint = match.group(0).rstrip('.,;:!?)"]}\'')
    try:
        response = requests.get(endpoint, timeout=10)
    except requests.RequestException as e:
        return {"error": str(e)}

    try:
        data = response.json()
    except ValueError:
        return {"data": response.text}

    if isinstance(data, dict):
        return data
    return {"data": data}
